#define R2D(a) mat2(cos(a+vec4(0,11,33,0)))

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float i,j,d=.1,e=0.;
    vec3 p,q=vec3(3,5,3);
    fragColor=vec4(0.);

    for(i=0.;i++<64.&&d>1e-4;){
        p=vec3((fragCoord.xy-.5*iResolution.xy)/iResolution.y,e)*8.;
        p.x-=8.;p.y-=2.;
        p.yz*=R2D(iTime);

        for(j=0.;j++<8.;)
            p.xy*=R2D(.12),
            p=abs(p-q)-.005,
            d=min(max(p.x,p.z)/d/d,p.y),
            d-=dot(p,q)/1e4;
        e+=d*exp(d);

    }fragColor += vec4(exp(-p*q*e),1)*3./i;
}
